function comboRows(areas,style){
 const count=style===4?3:style===2?7:style===7?4:style===0?4:6;
 const pool=areas.flatMap((a,i)=>{
   let xs=groups[a]||[];
   if(style===3)xs=[...xs.filter(x=>/ケーブル|マシン|プレス|ロウ|プル|カール|デック|レッグ/.test(x)),...xs.filter(x=>!/ケーブル|マシン|プレス|ロウ|プル|カール|デック|レッグ/.test(x))];
   return xs.slice(0,Math.max(2,Math.ceil(count/areas.length)+1)).map((name,j)=>({name,rank:j,area:a,index:i}));
 });
 const result=[],seen=new Set();
 for(let r=0;r<8&&result.length<count;r++)for(const a of areas){const x=pool.find(z=>z.area===a&&z.rank===r&&!seen.has(z.name));if(x){seen.add(x.name);result.push(x.name);if(result.length===count)break}}
 return result.map((exercise,i)=>[exercise,style===0&&i<2?4:styles[style][2],styles[style][3],styles[style][4]]);
}
