 const history=db.sessions.filter(s=>s.id!==excludeId).sort((a,b)=>(b.startedAt||b.date).localeCompare(a.startedAt||a.date)).map(s=>({sets:s.sets.filter(x=>canonicalExercise(x.exercise)===canonicalExercise(name)&&x.done&&!x.warmup&&Number(x.reps)>0),mode:s.pairGroups?.some(g=>g.names?.includes(name))?'paired':'normal'})).filter(h=>h.sets.length).slice(0,8);
