let elapsedInterval=setInterval(updateElapsedClock,1000);
function updateElapsedClock(){const el=$('#atlasElapsed');if(!el)return;const s=db.sessions.find(x=>x.id===active);if(!s?.startedAt)return;const ms=Math.max(0,new Date(s.endedAt||Date.now()).getTime()-new Date(s.startedAt).getTime());const sec=Math.floor(ms/1000);el.textContent=[Math.floor(sec/3600),Math.floor(sec/60)%60,sec%60].map(x=>String(x).padStart(2,'0')).join(':')}
function timer(seconds){restUntil=seconds?Date.now()+seconds*1000:0;clearInterval(restHandle);restHandle=setInterval(updateTimer,250);updateTimer()}function updateTimer(){const el=$('#clock');if(!el)return;const n=Math.max(0,Math.ceil((restUntil-Date.now())/1000));el.textContent=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;if(!n)clearInterval(restHandle)}
function nutrition(){
 const entries=db.foods.filter(x=>x.date===foodDate),tot={kcal:sum(entries,'kcal'),protein:sum(entries,'protein'),fat:sum(entries,'fat'),carbs:sum(entries,'carbs')};
 const latest=morningWeights().at(-1);
 const weight=num(latest?.y)||num(db.settings.weightInput)||85;
 const mode=db.settings.goalMode||'cut';
 const activity=num(db.settings.activity)||30;
 const maintenance=Math.round(weight*activity);
 const kcal=Math.round((maintenance+(mode==='cut'?-400:mode==='gain'?250:0))/10)*10;
 const protein=Math.round(weight*(mode==='cut'?2.1:1.8));
 const fat=Math.round(weight*(mode==='gain'?0.9:0.8));
 const carbs=Math.max(0,Math.round((kcal-protein*4-fat*9)/4));
 const energy=protein*4+fat*9+carbs*4;
 const pct=[Math.round(protein*4/energy*100),Math.round(fat*9/energy*100),Math.round(carbs*4/energy*100)];
 const burn=dayBurn(foodDate);const adjustment=db.settings.exerciseAdjustment===true;const adjustedKcal=kcal+(adjustment?burn:0);const recommended={kcal:adjustedKcal,protein,fat,carbs:carbs+(adjustment?Math.round(burn/4):0)};

 const macroMetrics=[['kcal','CALORIES','カロリー','kcal'],['protein','PROTEIN','タンパク質','g'],['fat','FAT','脂質','g'],['carbs','CARBS','炭水化物','g']];
 const macroStatus=(value,target,unit)=>{
   const diff=round(value-target);const margin=unit==='kcal'?30:2;
   if(diff>margin)return {kind:'over',label:'オーバー',detail:`+${round(diff)} ${unit} 超過`};
   if(diff< -margin)return {kind:'under',label:'不足',detail:`あと ${round(-diff)} ${unit}`};
   return {kind:'ok',label:'目標達成',detail:'目標範囲内'};
 };
 const dailyCards=macroMetrics.map(([key,en,jp,unit])=>{
   const value=round(tot[key]),target=recommended[key],state=macroStatus(value,target,unit),percent=Math.round(value/Math.max(1,target)*100);
   return `<article class="intake-tile ${state.kind}"><div class="intake-top"><span class="intake-en">${en}</span><span class="status-pill ${state.kind}">${state.label}</span></div><div class="intake-name">${jp}</div><div class="intake-value">${value}<span> / ${target} ${unit}</span></div><div class="intake-track"><div class="intake-fill" style="width:${Math.min(100,percent)}%"></div></div><div class="intake-bottom"><strong>${state.detail}</strong><span>${percent}%</span></div></article>`;
 }).join('');
 const exceeded=macroMetrics.filter(([key,,,unit])=>macroStatus(tot[key],recommended[key],unit).kind==='over').map(x=>x[2]);
 const remaining=macroMetrics.filter(([key,,,unit])=>macroStatus(tot[key],recommended[key],unit).kind==='under').map(x=>x[2]);
 const overview=entries.length===0?'まだ食事記録がありません。記録すると不足・超過を表示します。':exceeded.length?`${exceeded.join('・')}が目標を超えています。`:remaining.length?`${remaining.join('・')}が目標未満です。`:'4項目とも目標範囲内です。';
 const modeNames={cut:'減量・筋量維持',maintain:'体重維持・パフォーマンス',gain:'筋肥大・緩やかな増量'};
 $('#app').innerHTML=`<section class="card"><div class="eyebrow">NUTRITION STRATEGY</div><h2>目標体型からPFCを設計</h2><form id="nutritionPlan" class="stack"><div><label>目標</label><select name="goalMode"><option value="cut" ${mode==='cut'?'selected':''}>減量・筋量維持</option><option value="maintain" ${mode==='maintain'?'selected':''}>体重維持・パフォーマンス</option><option value="gain" ${mode==='gain'?'selected':''}>筋肥大・緩やかな増量</option></select></div><div class="grid">${field('weightInput','現在の体重 kg',weight)}${field('targetWeight','目標体重 kg',db.settings.targetWeight||80)}</div><div><label>活動量の目安</label><select name="activity">${[[27,'低め（座り仕事中心）'],[30,'標準（週3〜4回トレーニング）'],[33,'高め（活動量が多い）']].map(([n,t])=>`<option value="${n}" ${activity===n?'selected':''}>${t}</option>`).join('')}</select></div><button>目標からPFCを再計算</button></form><p class="note">${esc(modeNames[mode])}の初期推定。最新の体重記録がある場合はそれを優先。維持カロリーは体重×活動係数で概算しています。</p><div class="stats" style="margin-top:14px"><div class="stat"><small>目標 kcal</small><b>${kcal}</b></div><div class="stat"><small>体重</small><b>${round(weight)} kg</b></div><div class="stat"><small>目標体重</small><b>${db.settings.targetWeight||80} kg</b></div></div><h3 style="margin-top:16px">推奨PFCバランス</h3><div class="macro-cards">${[['P','タンパク質',protein,pct[0],'#d7b87c'],['F','脂質',fat,pct[1],'#82b5a4'],['C','炭水化物',carbs,pct[2],'#8baee1']].map(([key,label,grams,percent,color])=>`<div class="macro"><div class="row"><strong>${key} · ${label}</strong><strong>${grams} g</strong></div><div class="bar"><div style="width:${percent}%;background:${color}"></div></div><small>${percent}%（エネルギー比）</small></div>`).join('')}</div><p class="note">目安：体重の7日平均を2〜3週間確認し、変化が想定と異なる場合は摂取量を調整。体脂肪率・筋力の変化も合わせて判断してください。</p></section>
 <section class="card"><div class="eyebrow">WORKOUT ENERGY · ESTIMATE</div><h3>トレーニング消費カロリー</h3><div class="stats"><div class="stat"><small>運動消費</small><b>${burn} kcal</b></div><div class="stat"><small>基準目標</small><b>${kcal} kcal</b></div><div class="stat"><small>補正後目標</small><b>${adjustedKcal} kcal</b></div></div><label class="exercise-adjust"><input id="exerciseAdjustment" type="checkbox" ${adjustment?'checked':''}>運動消費分を摂取目標に加算（任意）</label><p class="note">消費量はトレーニング時間・体重・完了セット数を用いたMET法の概算です。日常活動を含む既存の摂取目標に運動分を足すと二重計上になる場合があります。P・Fは据え置き、追加エネルギーはCへ配分します。終了時刻のないセッションは算入しません。</p></section><section class="card intake-dashboard"><div class="eyebrow">DAILY NUTRITION · LIVE BALANCE</div><div class="row intake-header"><div><h2>1日のPFCバランス</h2><p class="note">目標と比較して、不足・超過をひと目で確認</p></div><span class="daily-mark">${entries.length}件</span></div><div class="intake-date"><label>記録日</label><input id="foodDate" type="date" value="${foodDate}"></div><div class="intake-summary"><span class="summary-dot"></span><span>${overview}</span></div><div class="intake-grid">${dailyCards}</div><p class="note">「不足」はその日の記録済み摂取量が目標未満という意味です。食事途中なら正常です。目標値は推定値で、脂質・炭水化物は厳密な上限ではありません。</p></section>
 <section class="card"><h3>食べたものを記録</h3><form id="foodForm" class="stack"><div><label>食材を検索</label><input id="foodSearch" type="search" placeholder="例：コーヒー、牛乳、卵、鶏むね" autocomplete="off"><label>選択中の食材</label><div id="foodChosen" class="chosen-food">食材が選択されていません</div><input type="hidden" name="food" id="foodSelect" value=""><div class="food-picker-actions"><button type="button" class="secondary" id="showAllFood">食材一覧を開く</button><button type="button" class="secondary" id="choosePowder">プロテイン粉末</button><button type="button" class="secondary" id="chooseCustom">自由入力</button></div><div id="foodResults" class="food-results hidden" role="listbox" aria-label="食材の検索結果"></div></div><div id="customFood" class="hidden stack">${field('name','食材名','','text')}${field('kcal','1食分のカロリー (kcal)',0)}${field('protein','1食分のタンパク質 (g)',0)}${field('fat','1食分の脂質 (g)',0)}${field('carbs','1食分の炭水化物 (g)',0)}</div><div id="powderFood" class="hidden stack">
 <p class="note">製品ラベルの「1杯あたり」の数値を入力。水で割る場合は粉末分だけ記録してください。</p>
 ${field('powderName','商品名','プロテイン粉末','text')}
 <div class="grid">${field('powderProtein','1杯のP (g)',25)}${field('powderFat','1杯のF (g)',2)}${field('powderCarbs','1杯のC (g)',3)}${field('powderKcal','1杯のkcal（空欄ならPFCから計算）','')}</div>
 ${field('servings','飲んだ杯数',1)}
 </div><div id="gramsField">${field('grams','食べた量 (g)',100)}<p class="note" id="portionNote">100gあたりの栄養値から計算</p></div><div><label>食事区分</label><select name="meal">${option(['朝食','昼食','夕食','間食'],(new Date().getHours()<5?'間食':new Date().getHours()<11?'朝食':new Date().getHours()<16?'昼食':new Date().getHours()<21?'夕食':'間食'))}</select></div><button>食事を記録</button></form><p class="note">食材を検索すると候補が画面内に表示されます。大きな選択メニューは開きません。栄養値は100gあたりの概算で、商品ラベルや調理状態を優先してください。プロテイン粉末は1杯あたりのP・F・Cを個別入力できます。自由入力では1食分の栄養表示をそのまま入力できます。食品ごとの数値は概算です。</p></section>
 <section class="card"><h3>${foodDate} の食事履歴</h3>${entries.map(x=>`<div class="row exercise"><div><b>${esc(x.name)}</b><div class="note">${esc(x.meal||'食事')} · ${x.servings!=null?round(x.servings)+'杯':x.unit&&x.quantity!=null?round(x.quantity)+x.unit:x.grams==null?'1食分':round(x.grams)+'g'} · ${round(x.kcal)}kcal · P${round(x.protein)} F${round(x.fat)} C${round(x.carbs)}</div></div><button class="danger" data-fooddel="${esc(x.id)}">削除</button></div>`).join('')||'<div class="empty">まだ記録がありません</div>'}</section>`;
 $('#exerciseAdjustment').onchange=e=>{db.settings.exerciseAdjustment=e.target.checked;save();render()};
 $('#nutritionPlan').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));db.settings.goalMode=v.goalMode;db.settings.activity=num(v.activity);db.settings.weightInput=num(v.weightInput);db.settings.targetWeight=num(v.targetWeight);save();render()};
 $('#foodDate').onchange=e=>{foodDate=e.target.value;render()};
 const chooseFood=(value)=>{
   const input=$('#foodSelect');input.value=String(value);
   $('#foodChosen').textContent=value==='powder'?'プロテイン粉末（PFC個別入力）':value==='custom'?'自由入力':pantry[Number(value)][0];
   $('#foodResults').classList.add('hidden');
   input.dispatchEvent(new Event('change'));
 };
 const drawFoodResults=()=>{
   const q=$('#foodSearch').value.trim().toLowerCase();
   const matches=pantry.map((item,i)=>({item,i})).filter(x=>!q||x.item[0].toLowerCase().includes(q)).slice(0,60);
   $('#foodResults').innerHTML=matches.map(({item,i})=>`<button type="button" class="food-result" data-foodidx="${i}" role="option"><span>${esc(item[0])}</span><small>${foodUnit(item[0]).unit==='mL'?'飲み物 · ':''}${Math.round(item[1])} kcal / 100${foodUnit(item[0]).unit==='mL'?'mL':'g'}</small></button>`).join('')||'<div class="note" style="padding:14px">該当する食材がありません。自由入力も利用できます。</div>';
   $('#foodResults').classList.remove('hidden');
   $$('#foodResults [data-foodidx]').forEach(btn=>btn.onclick=()=>chooseFood(btn.dataset.foodidx));
 };
 $('#foodSearch').oninput=drawFoodResults;
 $('#foodSearch').onfocus=drawFoodResults;
 $('#showAllFood').onclick=()=>{$('#foodSearch').value='';drawFoodResults();};
 $('#choosePowder').onclick=()=>chooseFood('powder');
 $('#chooseCustom').onclick=()=>chooseFood('custom');
 $('#foodSelect').onchange=e=>{
 const kind=e.target.value;
 $('#customFood').classList.toggle('hidden',kind!=='custom');
 $('#powderFood').classList.toggle('hidden',kind!=='powder');
 $('#gramsField').classList.toggle('hidden',kind==='custom'||kind==='powder');
 if(kind!==''&&kind!=='custom'&&kind!=='powder'){
  const entry=pantry[Number(kind)],portion=foodUnit(entry[0]);
  const amount=$('#gramsField [name=grams]'),label=$('#gramsField label');
  const previous=amount.dataset.unit;
  if(previous!==portion.unit){amount.value=portion.unit==='g'?100:portion.unit==='mL'?200:1;amount.dataset.unit=portion.unit}
  label.textContent=`食べた量 (${portion.unit})`;
  $('#portionNote').textContent=portion.unit==='個'?'卵1個＝可食部約50g（Mサイズの目安）':portion.unit==='パック'?'1パック約45gの目安':portion.unit==='枚'?'食パン1枚約60gの目安':portion.unit==='mL'?'飲料の量をmLで入力。商品ラベルを優先':'重量(g)で入力';
 }
};
$('#foodSelect').dispatchEvent(new Event('change'));
 $('#foodForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.food){$('#foodSearch').focus();drawFoodResults();return;}let item,ratio,grams;
 if(v.food==='powder'){
   const pp=num(v.powderProtein),ff=num(v.powderFat),cc=num(v.powderCarbs);
   const energy=v.powderKcal===''?pp*4+ff*9+cc*4:num(v.powderKcal);
   item=[(v.powderName||'プロテイン粉末').trim(),energy,pp,ff,cc];
   ratio=num(v.servings);grams=null;
 }else if(v.food==='custom'){
   item=[v.name,num(v.kcal),num(v.protein),num(v.fat),num(v.carbs)];
   ratio=1;grams=null;
 }else{
   item=pantry[Number(v.food)];
   const portion=foodUnit(item[0]);ratio=num(v.grams)*portion.grams/100;grams=portion.unit==='g'?num(v.grams):null;
 }
 if(!item||!item[0])return alert('食材名を入力してください');
 if(ratio<=0)return alert('摂取量または杯数を入力してください');
 db.foods.push({id:'f'+Date.now(),date:foodDate,name:item[0],grams,servings:v.food==='powder'?ratio:null,quantity:v.food!=='powder'&&v.food!=='custom'?num(v.grams):null,unit:v.food!=='powder'&&v.food!=='custom'?foodUnit(item[0]).unit:null,meal:v.meal,kcal:round(item[1]*ratio),protein:round(item[2]*ratio),fat:round(item[3]*ratio),carbs:round(item[4]*ratio)});save();render()};$$('[data-fooddel]').forEach(b=>b.onclick=()=>{if(confirm('削除しますか？')){db.foods=db.foods.filter(x=>x.id!==b.dataset.fooddel);save();render()}})
}
function progress(){
 const last=db.body.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];
 const lastMorning=morningWeights().at(-1),lastAverage=averageWeights().at(-1);
 const today=db.body.find(x=>x.date===iso())||{};
 const morning=morningWeights(),evening=db.body.filter(x=>x.weightEvening!==''&&x.weightEvening!=null&&Number(x.weightEvening)>0).map(x=>({date:x.date,y:Number(x.weightEvening)})).sort((a,b)=>a.date.localeCompare(b.date));
 $('#app').innerHTML=`<div class="card"><div class="eyebrow">BODY ANALYTICS</div><h2>身体の変化</h2><div class="stats"><div class="stat"><small>最新の朝 kg</small><b>${lastMorning?round(lastMorning.y):'—'}</b></div><div class="stat"><small>朝の7日平均 kg</small><b>${lastAverage?round(lastAverage.y,2):'—'}</b></div><div class="stat"><small>腕周り cm</small><b>${esc(last?.arm||'—')}</b></div></div><form id="bodyForm" class="stack" style="margin-top:15px">${field('date','測定日',iso(),'date')}<div class="grid">${field('weight','朝の体重 kg（任意）',today.weight??'')}${field('weightEvening','夜の体重 kg（任意）',today.weightEvening??'')}${field('bodyfat','体脂肪率 %',today.bodyfat??'')}${field('muscle','筋肉量 kg',today.muscle??'')}${field('waist','腹囲 cm',today.waist??'')}${field('arm','腕周り cm',today.arm??'')}${field('chest','胸囲 cm',today.chest??'')}</div><p class="note">朝：起床後・トイレ後・朝食前。夜：できるだけ同条件で任意記録。空欄は既存の値を保持します。</p><button>測定を保存</button></form></div>
 <div class="card"><h3>体重の推移</h3><p class="note">減量・増量の判定とGOALSの体重予測には朝の7日移動平均を使用。朝の記録が少ない間は取得済みデータの平均です。</p><h3>朝の体重</h3>${chart(morning,'kg')}<h3>朝の7日移動平均</h3>${chart(averageWeights(),'kg')}<h3>夜の体重（参考）</h3>${chart(evening,'kg')}<p class="note">朝晩の差は食事・水分などで変動し、脂肪の増減とは限りません。</p></div>
 <div class="card"><h3>その他の身体データ推移</h3><select id="bodyMetric">${[['bodyfat','体脂肪率'],['muscle','筋肉量'],['waist','腹囲'],['arm','腕周り'],['chest','胸囲']].map(([k,v])=>`<option value="${k}" ${bodyMetric===k?'selected':''}>${v}</option>`).join('')}</select>${chart(bodySeries(bodyMetric==='weight'?'bodyfat':bodyMetric),bodyMetric==='bodyfat'?'%':bodyMetric==='muscle'?'kg':'cm')}</div>
 <div class="card"><h3>種目別成長グラフ</h3><div class="grid"><div><label>種目</label><select id="chartExercise">${option([...new Set([...allExercises,...db.sessions.flatMap(s=>s.sets.map(x=>x.exercise))])],chartExercise)}</select></div><div><label>指標</label><select id="chartMetric">${[['e1rm','推定1RM'],['weight','最大使用重量'],['volume','1セッション最大セット負荷']].map(([k,t])=>`<option value="${k}" ${chartMetric===k?'selected':''}>${t}</option>`).join('')}</select></div></div>${chart(strengthSeries(chartExercise,chartMetric),'kg')}<p class="note">推定1RM = 重量 × (1 + 回数/30)。12回以下を対象にした簡易推定。</p></div>
 <div class="card"><h3>身体記録</h3>${db.body.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,15).map(x=>`<div class="row exercise"><small>${esc(x.date)} · 朝${x.weight||'—'}kg / 夜${x.weightEvening||'—'}kg · 腕${x.arm||'—'}cm</small><button class="danger" data-bodydel="${esc(x.date)}">削除</button></div>`).join('')||'<div class="empty">まだ記録がありません</div>'}</div>`;
 $('#bodyForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.date)return;const existing=db.body.find(x=>x.date===v.date)||{date:v.date};const merged={...existing};for(const [k,value] of Object.entries(v))if(k==='date'||value!=='')merged[k]=value;db.body=db.body.filter(x=>x.date!==v.date);db.body.push(merged);save();render()};
 $('#bodyMetric').onchange=e=>{bodyMetric=e.target.value;render()};$('#chartExercise').onchange=e=>{chartExercise=e.target.value;render()};$('#chartMetric').onchange=e=>{chartMetric=e.target.value;render()};$$('[data-bodydel]').forEach(b=>b.onclick=()=>{if(confirm('削除しますか？')){db.body=db.body.filter(x=>x.date!==b.dataset.bodydel);save();render()}})
}
function goals(){const choices=[...new Set([...allExercises,...db.sessions.flatMap(s=>s.sets.map(x=>x.exercise))])];$('#app').innerHTML=`<div class="card"><div class="eyebrow">MISSION OBJECTIVES</div><h2>最終目標と短期目標</h2><p class="note">最終目標は自分で設定。短期目標は直近の実測記録から4週間先を試算します。筋力・身体計測の予測は不確実です。</p>${db.goals.map(g=>{const pts=g.kind==='strength'?strengthSeries(g.name):bodySeries(({体重:'weight',腕周り:'arm',腹囲:'waist',胸囲:'chest',体脂肪率:'bodyfat'})[g.name]||'weight');const last=pts.at(-1)?.y;const fc=forecast(pts,num(g.target));const short=pts.length>=4?forecast(pts,round((last||0)+(num(g.target)-(last||0))*0.25)):{text:'データ収集中',detail:'まずは継続記録'};return `<div class="exercise"><div class="row"><b>${esc(g.name)}</b><button class="danger" data-goaldel="${esc(g.id)}">削除</button></div><div class="row" style="margin:9px 0"><div><small>現在</small><h2>${last==null?'—':round(last)}</h2></div><div><small>最終目標</small><h2 class="gold">${esc(g.target)}</h2></div></div><div class="bar"><div style="width:${last==null?0:Math.min(100,100*last/Math.max(1,num(g.target)))}%"></div></div><div class="row" style="margin-top:12px"><span class="pill">到達予測 ${fc.text}</span><span class="pill">短期目標 ${short.text}</span></div><p class="note">${esc(fc.detail)}</p>${chart(pts,g.kind==='strength'?'kg':'')}</div>`}).join('')}</div><div class="card"><h3>目標を追加</h3><form id="goalForm" class="stack"><div><label>目標種類</label><select name="kind" id="goalKind"><option value="strength">筋力（推定1RM）</option><option value="body">身体測定</option></select></div><div><label>対象</label><select name="name" id="goalName">${option(choices,'ベンチプレス')}</select></div>${field('target','最終目標値',100)}<button>目標を登録</button></form></div>`;$('#goalKind').onchange=e=>{$('#goalName').innerHTML=option(e.target.value==='strength'?choices:['体重','腕周り','腹囲','胸囲','体脂肪率'],'')};$('#goalForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));db.goals.push({id:'g'+Date.now(),kind:v.kind,name:v.name,target:num(v.target)});save();render()};$$('[data-goaldel]').forEach(b=>b.onclick=()=>{if(confirm('目標を削除しますか？')){db.goals=db.goals.filter(g=>g.id!==b.dataset.goaldel);save();render()}})}

function settings(){const s=db.settings;$('#app').innerHTML=`<div class="card"><div class="eyebrow">SYSTEM SETTINGS</div><h2>データ管理</h2><p class="note">PFC目標と目標体型の設定は「FOOD」タブに移動しました。ここではバックアップと復元を管理できます。</p></div><div class="card"><h3>データのバックアップ</h3><p class="note">v1の記録がこの端末にあれば初回起動時に可能な範囲で移行します。公開URLを変えるとブラウザの保存領域が別になる場合があります。更新前に必ずJSONを書き出してください。</p><div class="buttons"><button id="export">JSON書き出し</button><button class="secondary" id="import">JSON復元</button></div><input id="importFile" type="file" accept="application/json,.json"></div><div class="card"><h3>使い方</h3><p class="note">TRAINで部位・8種類のプランを選び、セットを記録。種目変更で代替種目を自由入力。FOODで食材ごとに個・g・mLなどを入力。STATSで朝晩の体重と身体と筋力の推移を確認。GOALSで最終目標と到達予測を表示します。</p></div>`;$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mission-reacher-backup-${iso()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{try{const v=JSON.parse(await e.target.files[0].text());if(!Array.isArray(v.sessions)||!Array.isArray(v.foods)||!Array.isArray(v.body)||!Array.isArray(v.goals)||!v.settings)throw Error('invalid');if(confirm('現在の記録をすべてバックアップで置き換えますか？')){db={...fresh(),...v,settings:{...fresh().settings,...v.settings}};save();render()}}catch{alert('バックアップ形式を確認してください')}}}
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
